const listAssets = `-- name: ListAssets :many

SELECT a.id, a.company_id, a.code, a.name, a.category_id, a.acquired_on, a.cost, a.residual, a.method, a.life_months, a.depreciation_start, a.asset_account_id, a.accum_account_id, a.expense_account_id, a.fiscal_group, a.fiscal_method, a.opening_accum, a.opening_month, a.location, a.custodian, a.notes, a.branch_id, a.department_id, a.status, a.disposed_on, a.created_at, a.created_by, a.version, c.name AS category_name, coalesce(d.total, 0)::numeric AS depreciated
FROM asset.assets a
JOIN asset.categories c ON c.id = a.category_id
LEFT JOIN LATERAL (
  SELECT sum(l.amount) AS total FROM asset.depreciation_lines l WHERE l.asset_id = a.id
) d ON true
WHERE a.company_id = $1
ORDER BY a.status, lower(a.code)
`

type ListAssetsRow struct {
	ID                uuid.UUID
	CompanyID         uuid.UUID
	Code              string
	Name              string
	CategoryID        uuid.UUID
	AcquiredOn        civil.Date
	Cost              money.Amount
	Residual          money.Amount
	Method            string
	LifeMonths        int32
	DepreciationStart civil.Date
	AssetAccountID    uuid.UUID
	AccumAccountID    *uuid.UUID
	ExpenseAccountID  *uuid.UUID
	FiscalGroup       string
	FiscalMethod      string
	OpeningAccum      money.Amount
	OpeningMonth      *civil.Date
	Location          string
	Custodian         string
	Notes             string
	BranchID          *uuid.UUID
	DepartmentID      *uuid.UUID
	Status            string
	DisposedOn        *civil.Date
	CreatedAt         time.Time
	CreatedBy         *uuid.UUID
	Version           int32
	CategoryName      string
	Depreciated       money.Amount
}

// Aset ---------------------------------------------------------------------------------
func (q *Queries) ListAssets(ctx context.Context, companyID uuid.UUID) ([]ListAssetsRow, error) {
	rows, err := q.db.Query(ctx, listAssets, companyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListAssetsRow
	for rows.Next() {
		var i ListAssetsRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Code,
			&i.Name,
			&i.CategoryID,
			&i.AcquiredOn,
			&i.Cost,
			&i.Residual,
			&i.Method,
			&i.LifeMonths,
			&i.DepreciationStart,
			&i.AssetAccountID,
			&i.AccumAccountID,
			&i.ExpenseAccountID,
			&i.FiscalGroup,
			&i.FiscalMethod,
			&i.OpeningAccum,
			&i.OpeningMonth,
			&i.Location,
			&i.Custodian,
			&i.Notes,
			&i.BranchID,
			&i.DepartmentID,
			&i.Status,
			&i.DisposedOn,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.Version,
			&i.CategoryName,
			&i.Depreciated,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

